1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	import org.springframework.samples.petclinic.util.CityRegions;
12	import org.springframework.samples.petclinic.util.MembershipLevels;
13	
14	import java.util.Collection;
15	import java.util.List;
16	
17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
24	    @Mapping(target = "initials", expression = "java(initials(owner))")
25	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
26	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
27	    @Mapping(target = "locality", expression = "java(locality(owner))")
28	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
29	    OwnerDto toOwnerDto(Owner owner);
30	
31	    /** Format an owner's name as 'LastName, FirstName' for display. */
32	    default String displayName(Owner owner) {
33	        return owner.getLastName() + ", " + owner.getFirstName();
34	    }
35	
36	    /** Upper-cased first letters of first and last name, dot-separated with a trailing dot (e.g. 'J.S.'). */
37	    default String initials(Owner owner) {
38	        return initial(owner.getFirstName()) + initial(owner.getLastName());
39	    }
40	
41	    private static String initial(String name) {
42	        return Character.toUpperCase(name.charAt(0)) + ".";
43	    }
44	
45	    /**
46	     * Derive the membership number '&lt;customerCode&gt;-M&lt;YY&gt;', where YY is the last
47	     * two digits of the registration date year (e.g. 'SYD-SMI-0007-M26'). Returns null when
48	     * either source field is absent.
49	     */
50	    default String membershipNumber(Owner owner) {
51	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
52	            return null;
53	        }
54	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
55	    }
56	
57	    /**
58	     * Derive the owner's locality (canonical region) from their city using the fixed
59	     * city-to-region table, or 'UNKNOWN' when the city is not in the table.
60	     */
61	    default String locality(Owner owner) {
62	        return CityRegions.localityOf(owner.getCity());
63	    }
64	
65	    /** Derive the owner's numeric membership level (1 to 3). */
66	    default Integer membershipLevel(Owner owner) {
67	        return MembershipLevels.of(owner);
68	    }
69	
70	    /** Derive the owner's preferred contact method: EMAIL when an email is present, otherwise PHONE. */
71	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
72	        return owner.hasEmail() ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
73	    }
74	
75	    Owner toOwner(OwnerDto ownerDto);
76	
77	    @Mapping(target = "id", ignore = true)
78	    @Mapping(target = "pets", ignore = true)
79	    Owner toOwner(OwnerFieldsDto ownerDto);
80	
81	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
82	
83	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
84	
85	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
86	        OwnerPageDto ownerPageDto = new OwnerPageDto();
87	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
